module fsm #(
    parameter s0 = 3'b000,
    parameter s1 = 3'b001,
    parameter s2 = 3'b010,
    parameter s3 = 3'b011,
    parameter s4 = 3'b100,
    parameter s5 = 3'b101
) (
    input IN,
    output reg MATCH,
    input CLK,
    input RST
);
    reg [2:0] current_state, next_state;

    parameter S0 = 3'd0;
    parameter S1 = 3'd1;
    parameter S2 = 3'd2;
    parameter S3 = 3'd3;
    parameter S4 = 3'd4;
    parameter S5 = 3'd5;

    always @(posedge CLK or posedge RST) begin
        if(RST) current_state <= S0;
        else    current_state <= next_state;
    end

    always @(*) begin
        case(current_state)
            S0: begin
                if(IN==1) next_state = S1; else next_state = S0;
            end

            S1: begin
                if(IN==0) next_state = S2; else next_state = S0;
            end

            S2: begin
                if(IN==0) next_state = S3; else next_state = S0;
            end

            S3: begin
                if(IN==1) next_state = S4; else next_state = S0;
            end

            S4: begin
                if(IN==1) next_state = S5; else next_state = S0;
            end

            S5: begin
                if(IN==1) next_state = S1; else next_state = S2;
            end

            default: next_state = S0;
        endcase
    end

    assign MATCH = (current_state == S5 && IN == 1) ? 1 : 0;
endmodule
